CREATE TABLE claim_assessments(project_id TEXT NOT NULL REFERENCES projects(id),task_id TEXT NOT NULL REFERENCES mission_tasks(id) ON DELETE CASCADE,claim_index INTEGER NOT NULL,result_hash TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN ('accept','revise','reject')),reason TEXT NOT NULL,reviewer TEXT NOT NULL REFERENCES user(id),updated_at TEXT NOT NULL,PRIMARY KEY(task_id,claim_index,result_hash));
